#!/usr/bin/env bash
# Offline deployment for servers that cannot reach GitHub.
#
# Writes the verified runtime files directly (no string matching, no git history needed).
# Safe to re-run. Generated from commit 7e40eac.
#
#   scp offline-fix-all.sh ubuntu@SERVER:~/InvestingPro/
#   cd ~/InvestingPro && bash offline-fix-all.sh
#   sudo docker compose up -d --build
#
set -euo pipefail
ROOT="${1:-.}"
[ -f "$ROOT/modules/macro-dashboard/web/allocation.tsx" ] || {
  echo "找不到项目文件。把项目根目录作为参数：bash offline-fix-all.sh ~/InvestingPro"; exit 1;
}
python3 - "$ROOT" <<'PY'
import base64, json, pathlib, sys
root = pathlib.Path(sys.argv[1])
FILES = json.loads(r'''{"modules/macro-dashboard/normalize.ts":"","modules/macro-dashboard/web/allocation.tsx":"","modules/macro-dashboard/web/report.tsx":"","modules/macro-dashboard/web/report-now.tsx":"","modules/macro-dashboard/server.ts":"","apps/web/app/features/admin/action.ts":""}''')
for rel, encoded in FILES.items():
    target = root / rel
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_bytes(base64.b64decode(encoded))
    print("wrote", rel)
PY
echo "完成。现在必须重建镜像：sudo docker compose up -d --build"
echo "验证：git log -1 --oneline 与硬刷新 /dashboard/allocation、/dashboard/report"
